import requests

BASE_URL = "https://api.socbench.example"
session = requests.Session()

# Monitor shipments currently in transit.
tracking_response = session.get(f"{BASE_URL}/inventory-tracking")
tracking_response.raise_for_status()
tracking_data = tracking_response.json()

# Retrieve all available products and their categories for cross-verification.
products_response = session.get(f"{BASE_URL}/products")
products_response.raise_for_status()
products_data = products_response.json()

# Check restocking progress for the products identified in the tracking data.
def extract_records(data):
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        for key in ("products", "shipments", "items", "data", "results"):
            value = data.get(key)
            if isinstance(value, list):
                return value
    return []

product_records = extract_records(products_data)
tracking_records = extract_records(tracking_data)

product_ids = {
    str(record[key])
    for record in product_records
    if isinstance(record, dict)
    for key in ("product_id", "productId", "id", "upc")
    if record.get(key) is not None
}
tracked_product_ids = {
    str(record[key])
    for record in tracking_records
    if isinstance(record, dict)
    for key in ("product_id", "productId", "upc")
    if record.get(key) is not None
}
restock_ids = sorted(product_ids | tracked_product_ids)

restock_response = session.get(
    f"{BASE_URL}/restock-status",
    params={"product_ids": ",".join(restock_ids)},
)
restock_response.raise_for_status()
restock_data = restock_response.json()

# Submit price update requests only for products with category-specific
# inventory discrepancies or needs supported by the retrieved data.
restock_records = extract_records(restock_data)
restock_by_product = {
    str(record[key]): record
    for record in restock_records
    if isinstance(record, dict)
    for key in ("product_id", "productId", "upc")
    if record.get(key) is not None
}

for product in product_records:
    if not isinstance(product, dict):
        continue

    product_id = next(
        (
            str(product[key])
            for key in ("product_id", "productId", "id", "upc")
            if product.get(key) is not None
        ),
        None,
    )
    if product_id is None:
        continue

    restock = restock_by_product.get(product_id, {})
    category = product.get("category") or product.get("category_name")
    discrepancy = (
        product.get("inventory_discrepancy")
        or product.get("discrepancy")
        or restock.get("inventory_discrepancy")
        or restock.get("discrepancy")
    )
    suggested_changes = (
        product.get("suggested_price_changes")
        or product.get("suggested_price")
        or restock.get("suggested_price_changes")
        or restock.get("suggested_price")
    )

    if category is None or not discrepancy or suggested_changes is None:
        continue

    payload = {
        "product_id": product_id,
        "category": category,
        "inventory_discrepancy": discrepancy,
        "restock_status": restock,
        "suggested_changes": suggested_changes,
    }
    response = session.post(f"{BASE_URL}/request_update", json=payload)
    response.raise_for_status()

